  ('32c899c5-7b42-57ad-93bc-99494d22bf7b', '000732c2-ef66-583d-9659-4419342671b8', 'A', '6', false, 0),
  ('73e40696-b4a7-5853-b998-c99049037456', '000732c2-ef66-583d-9659-4419342671b8', 'B', '7', false, 1),
