  ('17d38069-27cd-5f06-bbfd-009637449956', '7cd29066-7486-55d1-ad2e-c06f07909456', 'A', 'Amlodipine', false, 0),
  ('09dcc97b-07ec-5e1d-a63a-19f645e96810', '7cd29066-7486-55d1-ad2e-c06f07909456', 'B', 'Spironolactone', true, 1),
